%[text] ### Problem 1: Subspace Identification Methods (SIM)
%[text] We'll start by splitting the data into training and validation sets for both the small and large dataset.
load("p_dat.mat", "p_dat")

% 1001 samples, t = 0 to 500 s.
Ts = 0.5;
t = (0:1000)' * Ts;

% split - small vs large
small = p_dat{1};
large = p_dat{2};

% split train vs validation
small_train = small(1:501, :);
small_val   = small(502:end, :);

large_train = large(1:501, :);
large_val   = large(502:end, :);

t_train = t(1:501);
t_val   = t(502:end);

% split input vs output
u_small_train = small_train(:, 1:3);
y_small_train = small_train(:, 4:6);

u_large_train = large_train(:, 1:3);
y_large_train = large_train(:, 4:6);

u_small_val = small_val(:, 1:3);
y_small_val = small_val(:, 4:6);

u_large_val = large_val(:, 1:3);
y_large_val = large_val(:, 4:6);


%%\ Inspect the 3-input, 3-output training data
figure %[output:2d6c2d13]
tiledlayout(2, 2, "TileSpacing", "compact", "Padding", "compact") %[output:2d6c2d13]

% Small-amplitude inputs
nexttile %[output:2d6c2d13]
plot(t_train, u_small_train, "LineWidth", 1) %[output:2d6c2d13]
grid on %[output:2d6c2d13]
title("Small-amplitude training data: inputs") %[output:2d6c2d13]
xlabel("Time (s)") %[output:2d6c2d13]
ylabel("Input value") %[output:2d6c2d13]
legend("u_1", "u_2", "u_3", "Location", "best") %[output:2d6c2d13]

% Small-amplitude outputs
nexttile %[output:2d6c2d13]
plot(t_train, y_small_train, "LineWidth", 1) %[output:2d6c2d13]
grid on %[output:2d6c2d13]
title("Small-amplitude training data: outputs") %[output:2d6c2d13]
xlabel("Time (s)") %[output:2d6c2d13]
ylabel("Output value") %[output:2d6c2d13]
legend("y_1", "y_2", "y_3", "Location", "best") %[output:2d6c2d13]

% Large-amplitude inputs
nexttile %[output:2d6c2d13]
plot(t_train, u_large_train, "LineWidth", 1) %[output:2d6c2d13]
grid on %[output:2d6c2d13]
title("Large-amplitude training data: inputs") %[output:2d6c2d13]
xlabel("Time (s)") %[output:2d6c2d13]
ylabel("Input value") %[output:2d6c2d13]
